CREATE TABLE `users` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `email` VARCHAR(255) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `phone` VARCHAR(30) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `users_email_key`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `companies` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(160) NOT NULL, `sector` VARCHAR(100) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `companies_name_idx`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `stocks` (`id` INTEGER NOT NULL AUTO_INCREMENT, `company_id` INTEGER NOT NULL, `symbol` VARCHAR(20) NOT NULL, `exchange` VARCHAR(30) NOT NULL, `currency` CHAR(3) NOT NULL DEFAULT 'INR', `current_price` DECIMAL(19,4) NOT NULL DEFAULT 0, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `stocks_company_id_idx`(`company_id`), INDEX `stocks_symbol_idx`(`symbol`), UNIQUE INDEX `stocks_symbol_exchange_key`(`symbol`, `exchange`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `buy_transactions` (`id` INTEGER NOT NULL AUTO_INCREMENT, `user_id` INTEGER NOT NULL, `stock_id` INTEGER NOT NULL, `quantity` DECIMAL(19,6) NOT NULL, `price_per_share` DECIMAL(19,4) NOT NULL, `trade_date` DATETIME(3) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `buy_transactions_user_id_trade_date_idx`(`user_id`, `trade_date`), INDEX `buy_transactions_user_id_stock_id_idx`(`user_id`, `stock_id`), INDEX `buy_transactions_stock_id_trade_date_idx`(`stock_id`, `trade_date`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `sell_transactions` (`id` INTEGER NOT NULL AUTO_INCREMENT, `user_id` INTEGER NOT NULL, `stock_id` INTEGER NOT NULL, `quantity` DECIMAL(19,6) NOT NULL, `price_per_share` DECIMAL(19,4) NOT NULL, `trade_date` DATETIME(3) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `sell_transactions_user_id_trade_date_idx`(`user_id`, `trade_date`), INDEX `sell_transactions_user_id_stock_id_idx`(`user_id`, `stock_id`), INDEX `sell_transactions_stock_id_trade_date_idx`(`stock_id`, `trade_date`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `portfolio` (`id` INTEGER NOT NULL AUTO_INCREMENT, `user_id` INTEGER NOT NULL, `stock_id` INTEGER NOT NULL, `quantity_held` DECIMAL(19,6) NOT NULL DEFAULT 0, `average_cost` DECIMAL(19,4) NOT NULL DEFAULT 0, `updated_at` DATETIME(3) NOT NULL, INDEX `portfolio_user_id_idx`(`user_id`), UNIQUE INDEX `portfolio_user_id_stock_id_key`(`user_id`, `stock_id`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `stocks` ADD CONSTRAINT `stocks_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
