ALTER TABLE `buy_transactions` ADD CONSTRAINT `buy_transactions_stock_id_fkey` FOREIGN KEY (`stock_id`) REFERENCES `stocks`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
