ALTER TABLE `sell_transactions` ADD CONSTRAINT `sell_transactions_stock_id_fkey` FOREIGN KEY (`stock_id`) REFERENCES `stocks`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `portfolio` ADD CONSTRAINT `portfolio_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
